//! Upstream Tauri 2 mobile-plugin build (v2.tauri.app/develop/plugins/develop-mobile): one `allow-`/`deny-`
//! permission per command under `permissions/autogenerated`, and on an iOS target the Swift package in `ios/`
//! linked through swift-rs (with the tauri-api package copied to `.tauri/tauri-api`).
//! `register_listener`/`remove_listener` are the Swift `Plugin` base's, which `addPluginListener` calls.
const COMMANDS: &[&str] = &[
    "is_supported",
    "configure",
    "set_title",
    "set_scroll_button",
    "set_hidden",
    "set_background",
    "register_listener",
    "remove_listener",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).ios_path("ios").build();
}
